async fn check_rate_limit(con: &mut redis::aio::Connection, key: &str, now: f64, window: f64, limit: usize) -> Result<bool, redis::RedisError> {
    let clear_before = now - window;
    let _: () = redis::pipe()
        .atomic()
        .zrembyscore(key, 0.0, clear_before)
        .zadd(key, now, now)
        .zcard(key)
        .query_async(con).await?;
    let count: usize = redis::cmd("ZCARD").arg(key).query_async(con).await?;
    Ok(count <= limit)
}

