import threading
import atomic

class ConcurrentLSMNode:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.next = None

class EpochManager:
    def __init__(self):
        self.epoch = 0
        self.threads = threading.local()

    def enter(self):
        self.threads.epoch = self.epoch

    def leave(self):
        self.threads.epoch = None

class MemTable:
    def __init__(self):
        self.head = ConcurrentLSMNode(None, None)

    def put(self, key, value):
        new_node = ConcurrentLSMNode(key, value)
        new_node.next = self.head.next
        self.head.next = new_node

class LockFreeLSM:
    def __init__(self):
        self.active_memtable = atomic.AtomicReference(MemTable())
        self.immutable_memtable = None
        self.epoch_mgr = EpochManager()

    def write(self, key, value):
        self.epoch_mgr.enter()
        try:
            current_mem = self.active_memtable.get()
            current_mem.put(key, value)
        finally:
            self.epoch_mgr.leave()

    def rotate_memtable(self):
        old_mem = self.active_memtable.get()
        new_mem = MemTable()
        while not self.active_memtable.compare_and_set(old_mem, new_mem):
            old_mem = self.active_memtable.get()
        self.immutable_memtable = old_mem

