Node* atomicMeld(std::atomic<Node*>& root, Node* heap1, Node* heap2) {
    if (!heap1) return heap2;
    if (!heap2) return heap1;
    if (heap1->key > heap2->key) std::swap(heap1, heap2);

    Node* old_right = heap1->right.load();
    Node* merged = atomicMeld(root, old_right, heap2);

    while (!heap1->right.compare_exchange_weak(old_right, merged)) {
        merged = atomicMeld(root, old_right, heap2);
    }

    int left_npl = heap1->left.load() ? heap1->left.load()->npl : 0;
    int right_npl = heap1->right.load() ? heap1->right.load()->npl : 0;
    if (left_npl < right_npl) {
        Node* temp = heap1->left.load();
        heap1->left.store(heap1->right.load());
        heap1->right.store(temp);
    }
    heap1->npl = std::min(left_npl, right_npl) + 1;
    return heap1;
}

